class Solution {
public:
    int minimumK(vector<int>& nums) {
        for (long long k = 1;; k++) {
            long long ops = 0;
            for (int x : nums) ops += (x + k - 1) / k;
            if (ops <= k * k) return k;
        }
    }
};

