class Solution {
    public int minimumK(int[] nums) {
        int lo = 1, hi = 0;
        for (int x : nums) hi = Math.max(hi, x);
        while (lo < hi) {
            int mid = lo + (hi - lo) / 2;
            long ops = 0;
            for (int x : nums) ops += (x + mid - 1) / mid;
            if (ops <= (long) mid * mid) hi = mid;
            else lo = mid + 1;
        }
        return lo;
    }
}

