var minimumK = function(nums) {
    let lo = 1, hi = Math.max(...nums);
    const ops = k => nums.reduce((s, x) => s + Math.ceil(x / k), 0);
    while (lo < hi) {
        const mid = (lo + hi) >> 1;
        if (ops(mid) <= mid * mid) hi = mid;
        else lo = mid + 1;
    }
    return lo;
};
